prompt.text:
The source below is intended to export `highestPriority(records)`. `records` must be an array or cause `TypeError`. Every element must be a non-null, non-array object with a finite numeric `priority`; otherwise throw `TypeError`. Return the greatest priority number. Return `null` for an empty array. Preserve record order and do not mutate the array or its elements. Correct the single bug and return the complete source file.

```javascript
'use strict';

function highestPriority(records) {
  if (!Array.isArray(records)) {
    throw new TypeError('records must be an array');
  }
  if (records.length === 0) {
    return null;
  }

  const priorities = records.map((record) => {
    if (
      record === null ||
      typeof record !== 'object' ||
      Array.isArray(record) ||
      !Number.isFinite(record.priority)
    ) {
      throw new TypeError('each record must have a finite numeric priority');
    }
    return record.priority;
  });

  return Math.min(...priorities);
}

module.exports = { highestPriority };
```

