'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['highestPriority']);
const { highestPriority } = api;

const records = [
  { priority: -10, name: 'low' },
  { priority: 7.5, name: 'high' },
  { priority: 0 },
  { priority: 7.5, name: 'duplicate high' },
  { priority: -2 }
];
const orderBefore = records.slice();
const snapshots = records.map((record) => ({ ...record }));
assert.strictEqual(highestPriority(records), 7.5);
assert.deepStrictEqual(records, orderBefore);
for (let i = 0; i < records.length; i += 1) {
  assert.strictEqual(records[i], orderBefore[i]);
  assert.deepStrictEqual(records[i], snapshots[i]);
}

const empty = [];
assert.strictEqual(highestPriority(empty), null);
assert.deepStrictEqual(empty, []);
assert.strictEqual(highestPriority([{ priority: -4 }]), -4);
assert.strictEqual(highestPriority([{ priority: Number.MAX_VALUE }, { priority: -Infinity }].slice(0, 1)), Number.MAX_VALUE);

for (const invalid of [null, undefined, {}, 'records', 3, true]) {
  assert.throws(() => highestPriority(invalid), TypeError);
}

for (const invalidRecord of [
  null,
  undefined,
  [],
  3,
  'record',
  {},
  { priority: '10' },
  { priority: NaN },
  { priority: Infinity },
  { priority: -Infinity },
  { priority: new Number(4) }
]) {
  assert.throws(() => highestPriority([{ priority: 1 }, invalidRecord]), TypeError);
}

